package license

import (
	"crypto"
	"crypto/rsa"
	"crypto/sha256"
	"crypto/sha512"
	"crypto/x509"
	_ "embed"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"encoding/pem"
	"fmt"
	"net/http"
	"strings"

	"github.com/mattermost/mattermost/server/public/model"
	"github.com/mattermost/mattermost/server/v8/channels/utils"
)

//go:embed public-key.pem
var workspacePublicKey []byte

// Validator verifies licenses generated by the workspace license signer.
// The verifier is entirely local and never contacts an external service.
type Validator struct {
	publicKey []byte
}

var _ utils.LicenseValidatorIface = (*Validator)(nil)

func NewValidator() *Validator {
	return newValidator(workspacePublicKey)
}

func newValidator(publicKey []byte) *Validator {
	return &Validator{publicKey: append([]byte(nil), publicKey...)}
}

func (v *Validator) LicenseFromBytes(licenseBytes []byte) (*model.License, *model.AppError) {
	licenseJSON, err := v.ValidateLicense(licenseBytes)
	if err != nil {
		return nil, utils.NewLicenseValidationAppError("LicenseFromBytes", err)
	}

	var result model.License
	if err := json.Unmarshal([]byte(licenseJSON), &result); err != nil {
		return nil, model.NewAppError("LicenseFromBytes", "api.unmarshal_error", nil, "", http.StatusInternalServerError).Wrap(err)
	}
	if result.Features == nil {
		result.Features = &model.Features{}
	}
	result.Features.SetDefaults()
	// Mattermost 12.0 currently omits AutoTranslation from Features.SetDefaults.
	// Normalize it here, before the verified license reaches core, while
	// preserving an explicit false value from the signed payload.
	if result.Features.AutoTranslation == nil {
		result.Features.AutoTranslation = model.NewPointer(*result.Features.FutureFeatures)
	}

	return &result, nil
}

func (v *Validator) ValidateLicense(signed []byte) (string, error) {
	publicKey, err := parseRSAPublicKey(v.publicKey)
	if err != nil {
		return "", err
	}

	decoded, err := base64.StdEncoding.DecodeString(strings.TrimSpace(string(signed)))
	if err != nil {
		return "", fmt.Errorf("decode workspace license: %w", err)
	}

	signatureSize := publicKey.Size()
	if len(decoded) <= signatureSize {
		return "", fmt.Errorf("workspace license is too short")
	}

	licenseJSON := decoded[:len(decoded)-signatureSize]
	signature := decoded[len(decoded)-signatureSize:]
	digest := sha512.Sum512(licenseJSON)

	if err := rsa.VerifyPKCS1v15(publicKey, crypto.SHA512, digest[:], signature); err != nil {
		return "", fmt.Errorf("invalid workspace license signature: %w", err)
	}

	return normalizeLicenseID(licenseJSON, decoded)
}

func parseRSAPublicKey(publicKeyPEM []byte) (*rsa.PublicKey, error) {
	block, _ := pem.Decode(publicKeyPEM)
	if block == nil {
		return nil, fmt.Errorf("decode workspace public key PEM")
	}

	parsed, err := x509.ParsePKIXPublicKey(block.Bytes)
	if err != nil {
		return nil, fmt.Errorf("parse workspace public key: %w", err)
	}

	publicKey, ok := parsed.(*rsa.PublicKey)
	if !ok {
		return nil, fmt.Errorf("workspace public key is not RSA")
	}

	return publicKey, nil
}

func normalizeLicenseID(licenseJSON, signedBinary []byte) (string, error) {
	var fields map[string]json.RawMessage
	if err := json.Unmarshal(licenseJSON, &fields); err != nil {
		return "", fmt.Errorf("decode workspace license JSON: %w", err)
	}

	var id string
	if rawID, ok := fields["id"]; ok {
		_ = json.Unmarshal(rawID, &id)
	}
	if model.IsValidId(id) {
		return string(licenseJSON), nil
	}

	// The license record store requires a 26-character Mattermost ID. Deriving
	// it from the verified signed bytes keeps it stable across uploads and
	// server restarts without changing the signed license payload.
	hash := sha256.Sum256(signedBinary)
	stableID := hex.EncodeToString(hash[:])[:26]
	encodedID, err := json.Marshal(stableID)
	if err != nil {
		return "", fmt.Errorf("encode workspace license ID: %w", err)
	}
	fields["id"] = encodedID

	normalized, err := json.Marshal(fields)
	if err != nil {
		return "", fmt.Errorf("encode normalized workspace license: %w", err)
	}

	return string(normalized), nil
}
